const events=[{id:'quest',type:'СЮЖЕТ · ЗАДАНИЕ',title:'Картограф не вернулся с маяка',desc:'Новая зацепка для задания «Свет на мысе». Мира рассказала, что картограф ушёл к старому маяку.',source:'Мастер: «Мира говорит, что картограф пошёл к старому маяку. С тех пор его никто не видел».',time:'01:42',action:'Добавить зацепку'}, {id:'gold',type:'ЛИЧНОЕ · НАГРАДА',title:'Элиан получает 25 зм',desc:'Предложенное изменение: личное золото +25. Награда не распределяется между участниками автоматически.',source:'Мастер: «Мира отдаёт Элиану двадцать пять золотых за доставленное письмо».',time:'01:46',action:'Добавить 25 зм'}, {id:'damage',type:'МЕХАНИКА · УРОН',title:'Элиан получает 7 урона',desc:'Проверь итог после сопротивлений и других эффектов. Изменение будет применено только после подтверждения.',source:'Мастер: «Элиан, стрела попадает. Семь колющего урона».',time:'01:51',action:'Применить урон'}];
