function heading(kicker,title,sub,action=''){return `<div class="page-top"><div><div class="overline">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function resourceControls(level){
 if(SkazStorage.sheet?.())return level===undefined?'<section class="resource-controls" aria-label="Ручные ресурсы">'+SkazCharacterSheet.controls()+'</section>':'';
 return '<section class="resource-controls" aria-label="Быстрые ресурсы">'+[...[1,2,3].map((l,i)=>({key:'slot'+l,title:l+' круг',label:'Ячейка '+l+' круга',resource:{kind:'slot',level:l},value:state.slots[l],max:[4,3,2][i]})),{key:'inspiration',title:'Вдохновение барда · к8',label:'Вдохновение барда',resource:{kind:'inspiration'},value:state.inspiration,max:4}].filter(r=>level===undefined||r.key==='slot'+level).map(r=>SkazCharacterSheet.tracker({name:r.title,label:r.label,current:r.value,max:r.max,shape:r.key==='inspiration'?'diamond':'circle',allowed:SkazStorage.canResource?.()??SkazStorage.editable(),pending:SkazStorage.pendingResourceIndices?.(r.resource)||[],attributes:delta=>'data-resource="'+r.key+'" data-delta="'+delta+'"'})).join('')+'</section>';
}
function hero(){const sheet=SkazStorage.sheet?.();const stats=SkazStorage.stats?.()||{abilities:{str:8,dex:14,con:14,int:12,wis:10,cha:18},armorClass:14,initiative:2,speed:30};const signed=n=>(n>=0?"+":"−")+Math.abs(n);return heading(sheet?esc([sheet.ancestry,sheet.className,sheet.subclass].filter(Boolean).join(' · ')):'ПОЛУЭЛЬФ · БАРД · КОЛЛЕГИЯ ЗНАНИЙ','Твоя история продолжается','Тихая гавань. До старого маяка — полдня пути.',`<div class="character-edit">${SkazStorage.advancementScope?.()?'<button id="advance-class">Повысить уровень</button>':''}<button id="edit-sheet" class="secondary">Свой класс</button><button class="secondary" id="edit-profile">Изменить</button><button class="secondary" id="edit-stats">Характеристики</button><button class="secondary" id="edit-resources">Ресурсы</button></div>`)+`<div class="hero-grid"><section><div class="panel character"><div class="character-top"><div><div class="overline">${sheet?'РУЧНОЙ ЛИСТ':'ГОЛОС ПОБЕРЕЖЬЯ'}</div><div class="character-name">${esc(state.profile.name)}</div><p>${esc(state.profile.tagline)}</p></div><div class="level">${sheet?.level||5}<small>УРОВЕНЬ</small></div></div></div><div class="statrow"><div class="stat"><label>КЛАСС ДОСПЕХА</label><strong>${stats.armorClass}</strong></div><div class="stat"><label>ИНИЦИАТИВА</label><strong>${signed(stats.initiative)}</strong></div><div class="stat"><label>СКОРОСТЬ</label><strong>${stats.speed} <small style="font-size:11px">фт</small></strong></div></div></section></div><p class="small">${SkazStorage.manualStats?.()?"Ручные характеристики · КД, инициатива и скорость заданы итоговыми значениями":(sheet?"Статистики шаблона: настрой их под свой класс":"Характеристики шаблона барда 5 уровня")}</p><div class="spell-stats">${SkazCharacterSheet.spellTiles(stats,sheet)}</div><div class="abilities">${[['СИЛ','str'],['ЛОВ','dex'],['ТЕЛ','con'],['ИНТ','int'],['МДР','wis'],['ХАР','cha']].map(([title,id])=>`<div class="ability"><label>${title}</label><strong>${signed(Math.floor((stats.abilities[id]-10)/2))}</strong><small>${stats.abilities[id]}</small></div>`).join('')}</div><section class="panel hero-inventory"><div class="panel-title"><div><h2>Инвентарь</h2><p>${state.gold} зм · сохранённые предметы персонажа</p></div><button data-page="inventory">Открыть инвентарь →</button></div><p class="small">Расходники и предметы с зарядами — в начале списка.</p></section><div class="two-col" style="margin-top:20px">${sheet?SkazCharacterSheet.view():`<section class="panel demo-example"><div class="panel-title"><h2>Под рукой</h2><span class="tag">Демо действий</span></div><div class="action-row"><div><strong>Рапира</strong><small>Действие · 1к8 + 2 колющего</small></div><button data-roll="rapier" ${SkazStorage.manualStats?.()?'disabled title="Демо-бросок не учитывает ручные характеристики"':''}>+5 ↗</button></div><div class="action-row"><div><strong>Злая насмешка</strong><small>Заговор · Мудрость Сл 15 · 2к4</small></div><button data-spell="mockery">Читать</button></div><div class="action-row"><div><strong>Инвентарь</strong><small>Сохранённые предметы</small></div><button id="open-inventory">Открыть</button></div></section>`}<section class="panel session-card demo-example"><div class="panel-title"><h2>Нить приключения</h2><span class="tag accent">Демо сюжета</span></div><div class="overline" style="margin-top:24px">СВЕТ НА МЫСЕ</div><p class="quote">«Если маяк погас, значит, кто-то хотел, чтобы корабль не дошёл».</p><p>Мира, хозяйка трактира · Тихая гавань</p><button class="text-button" data-page="quests">Открыть задание →</button><button class="text-button" data-page="journal">${location.protocol==='file:'?(pending().length?pending().length+' события ждут подтверждения':'Все события разобраны'):'События текущей сессии'} →</button></section></div>`}
function pending(){return events.filter(e=>!state.accepted.includes(e.id)&&!state.dismissed.includes(e.id))}
function spellsPage(){if(location.protocol==='file:')return demoSpellsPage();return SkazSpellbook.view()+`<details class="demo-section"><summary>Демонстрационные заклинания и ячейки барда 5 уровня</summary>${demoSpellsPage()}</details>`}
function demoSpellsPage(){return heading('КНИГА ЗАКЛИНАНИЙ','Слова обретают силу','Харизма +4 · Атака заклинанием +7 · Сложность спасброска 15')+`<div class="notice"><button id="open-spellbook" class="primary">Мои заклинания из каталога</button><p><b>Ниже — 8 демонстрационных заклинаний.</b> Сохранённые записи каталога доступны отдельной кнопкой.</p> Описания здесь сокращены для проверки UX.</div><div class="filters"><input id="spell-search" aria-label="Найти заклинание" placeholder="Название на русском или английском…" value="${esc(spellQuery)}"><select id="spell-scope" aria-label="Доступность"><option value="all" ${spellFilter==='all'?'selected':''}>Весь каталог</option><option value="known" ${spellFilter==='known'?'selected':''}>Мои заклинания</option></select><select id="spell-level" aria-label="Круг заклинания"><option value="all">Все круги</option>${[0,1,2,3].map(l=>`<option value="${l}" ${String(l)===spellLevel?'selected':''}>${l===0?'Заговоры':l+' круг'}</option>`).join('')}</select></div><div id="spell-results" class="spell-grid">${spellCards()}</div>`}
function spellCards(){const list=spells.filter(s=>(spellFilter!=='known'||s.known)&&(spellLevel==='all'||s.level===Number(spellLevel))&&(s.name+' '+s.en).toLowerCase().includes(spellQuery.toLowerCase()));return list.length?list.map(s=>`<button class="spell" data-spell="${s.id}"><div class="spell-top"><span class="spell-level">${s.level===0?'<span data-ui-icon="magic"></span>':String(s.level).padStart(2,'0')}</span><span class="tag ${s.known?'accent':''}">${s.known?'Известно':'В каталоге'}</span></div><h3>${s.name}</h3><p>${s.desc}</p><div class="spell-meta"><span>${s.time}</span><span>${s.range}</span>${s.conc?'<span><span data-ui-icon="focus"></span> Концентрация</span>':''}</div></button>`).join(''):'<div class="empty full">Ничего не найдено. Попробуй другое название или убери фильтры.</div>'}
function journal(){return location.protocol==='file:'?demoJournal():heading(esc(SkazStorage.sessionTitle()),'Помнить главное','Сюжет, находки и решения — в одном месте.',`<button class="secondary" id="add-note">＋ Личная заметка</button>`)+SkazEvents.view()+`<section class="panel confirmed-journal"><h2>Журнал и личные заметки</h2><p>События сессии попадают в её архив. Личные заметки остаются у персонажа между сессиями.</p><div class="timeline">${[...state.journal,...state.notes].sort((a,b)=>b.at-a.at).map(e=>`<div class="timeline-entry"><time>${esc(e.time)} · ${esc(e.kind||'Заметка')}</time><h3>${esc(e.title)}</h3><p class="session-text">${esc(e.text||'')}</p></div>`).join('')||'<p>Подтверждённых записей пока нет.</p>'}</div><button class="secondary" id="export-journal">Скачать журнал</button></section>`}
function demoJournal(){return heading(esc(SkazStorage.sessionTitle()),'Помнить главное','Сюжет, находки и решения — в одном месте.',`<button class="secondary" id="add-note">＋ Заметка</button>`)+`<div class="notice"><b>Демо распознавания.</b> Показан заранее подготовленный разговор. Микрофон не включается, аудио не записывается.</div><div class="journal-grid"><section><div class="panel recording"><span class="live-dot"></span><div><strong>Общий микрофон</strong><div class="small" style="color:var(--muted)">${paused?'Демо приостановлено':'Пример обработки разговора'}</div></div><div class="wave">${[12,22,15,28,17,24,9].map(h=>`<i style="height:${paused?4:h}px"></i>`).join('')}</div><button id="pause" aria-label="${paused?'Продолжить':'Приостановить'} демо">${paused?'▶':'Ⅱ'}</button></div><div class="panel-title"><h2>Разобрать события</h2><span class="tag">Новых: ${pending().length}</span></div>${pending().map(e=>`<article class="event"><span class="overline">${e.type}</span><h3>${e.title}</h3><p>${e.desc}</p><div class="source">${e.time} · ${e.source}</div><div class="toolbar"><button class="primary" data-accept="${e.id}">${e.action}</button><button data-edit-event="${e.id}" aria-label="Исправить событие ${e.title}">Изменить</button><button class="text-button" data-dismiss="${e.id}">Пропустить</button></div></article>`).join('')||'<div class="panel empty">Нет предложенных событий.<br>Сохранённые записи доступны в журнале и архиве сессий.</div>'}${state.dismissed.length?'<button class="text-button" id="restore-events">Вернуть демо-события</button>':''}</section><section class="panel"><div class="panel-title"><h2>Журнал и личные заметки</h2><span class="tag">Личное</span></div><p class="small">Личные заметки сохраняются между сессиями. В архив входит только журнал сессии.</p><div class="timeline">${[...state.journal,...state.notes].sort((a,b)=>b.at-a.at).map(e=>`<div class="timeline-entry"><time>${esc(e.time)} · ${esc(e.kind||'Заметка')}</time><h3>${esc(e.title)}</h3><p>${esc(e.text||'')}</p></div>`).join('')}</div><button class="secondary" id="export-journal" style="width:100%">Скачать журнал</button></section></div>`}
function quests(){return location.protocol === 'file:' ? demoQuests() : heading('ЗАЦЕПКИ И ОБЕЩАНИЯ','Ни одна нить не потеряется','Твои задания и личные цели текущей кампании.')+SkazQuests.view()+`<details class="demo-map-details"><summary>Посмотреть демонстрационный сюжет</summary>${demoQuests()}</details>`}
function demoQuests(){return heading('ЗАЦЕПКИ И ОБЕЩАНИЯ','Ни одна нить не потеряется','Здесь только то, что известно твоему персонажу.')+`<div class="notice"><b>Демонстрационный сюжет.</b> Эти примеры не входят в сохранённые задания кампании.</div><div class="quest-list"><article class="panel quest"><div class="quest-icon"><span data-ui-icon="flag"></span></div><div><div class="overline">ОСНОВНАЯ НИТЬ · ${state.checks.q2?'ЗАВЕРШЕНО':'В ПРОЦЕССЕ'}</div><h2>Свет на мысе</h2><p>Выяснить, почему погас старый маяк и куда исчез картограф. Мира обещала помочь с лодкой, если вы вернётесь с новостями.</p>${[['q0','Расспросить Миру в трактире'],['q1','Добраться до старого маяка'],['q2','Найти картографа и узнать правду']].map(([id,t])=>`<label class="quest-check"><input type="checkbox" data-check="${id}" ${state.checks[id]??id==='q0'?'checked':''}>${t}</label>`).join('')}${state.accepted.includes('quest')?'<div class="notice" style="margin:15px 0 0"><b>Новая зацепка:</b> '+esc(state.eventEdits.quest||'Картограф ушёл к маяку. Источник: Мира, сессия 12.')+'</div>':''}</div><button class="secondary" data-place="lighthouse">На карте ↗</button></article><article class="panel quest"><div class="quest-icon"><span data-ui-icon="mail"></span></div><div><div class="overline">ЛИЧНОЕ · ${state.accepted.includes('gold')?'НАГРАДА ПОЛУЧЕНА':'ЗАБРАТЬ НАГРАДУ'}</div><h2>Письмо без подписи</h2><p>Письмо доставлено Мире. Она обещала Элиану 25 золотых. Отправитель попросил не называть его имени.</p><span class="tag accent">${state.accepted.includes('gold')?(state.eventEdits.gold??25)+' зм добавлено':'Награда: 25 зм'}</span></div><button data-page="journal">В журнал →</button></article></div>`}
function mapPage(){return location.protocol === 'file:' ? demoMapPage() : heading('МИР КАМПАНИИ','Места, которые вы открыли','Записывай только то, что узнал за игровым столом.')+SkazMap.view()+`<details class="demo-map-details"><summary>Посмотреть демонстрационную карту</summary>${demoMapPage()}</details>`}
function demoMapPage(){return heading('ПОБЕРЕЖЬЕ ТУМАНОВ','Мир, который вы открыли','Карта знаний партии. Выбери место, чтобы увидеть зацепки.')+`<div class="map-layout"><div class="map"><svg viewBox="0 0 700 600" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="var(--line)" stroke-width=".5"/></pattern><pattern id="trees" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M15 5l-8 15h16z" fill="none" stroke="var(--wash)" opacity=".3"/></pattern></defs><rect width="700" height="600" fill="var(--panel)"/><rect width="700" height="600" fill="url(#grid)"/><path d="M-20 0H535Q480 60 520 115T470 220Q570 260 440 360T390 600H0Z" fill="var(--raised)" stroke="var(--wash)" stroke-width="2"/><path d="M540 0Q480 80 535 125T490 220Q590 260 460 375T415 600" fill="none" stroke="var(--line)" stroke-width="2"/><path d="M50 90Q180 40 300 130L320 310 100 370Z" fill="url(#trees)"/><path d="M270 400Q310 340 355 315T455 150" fill="none" stroke="var(--accent)" stroke-width="2" stroke-dasharray="5 8"/><g fill="none" stroke="var(--wash)" opacity=".4"><path d="M40 490l35-60 35 60-12-10-23-37-24 39zM95 495l40-80 40 80M140 515l38-65 38 65"/><path d="M590 410h45m-30-15h45m-70 30h40M560 300h45m-10-15h35"/></g><text x="550" y="355" fill="var(--muted)" opacity=".5" font-family="Georgia" font-size="18" transform="rotate(-65 550 355)">МОРЕ ТУМАНОВ</text><g transform="translate(620 85)" fill="none" stroke="var(--accent)" opacity=".7"><path d="M0-25V25M-25 0H25M0-25l-5 10h10Z"/><circle r="18"/></g></svg><div class="map-caption">Северное побережье</div>${Object.entries(places).map(([id,p])=>`<button class="map-point ${place===id?'selected':''}" data-map-place="${id}" style="left:${p.x}%;top:${p.y}%">${id==='town'?'<span data-ui-icon="focus"></span>':'<span data-ui-icon="map"></span>'} ${p.title}</button>`).join('')}<div class="map-legend"><span data-ui-icon="focus"></span> Вы здесь &nbsp; <span data-ui-icon="map"></span> Известное место · Схематическая демо-карта</div></div><aside class="panel" id="place-details">${placeDetails()}</aside></div>`}
function placeDetails(){let p=places[place];return `<div class="overline">${p.type}</div><h2>${p.title}</h2><span class="tag accent">${p.status}</span><p class="map-note" style="margin-top:23px">${p.text}</p>${place==='lighthouse'?'<button class="text-button" data-page="quests">Связано: Свет на мысе →</button>':''}<div class="map-notes">${state.mapNotes.filter(n=>n.place===place).map(n=>`<div class="notice">${esc(n.text)}</div>`).join('')}</div><button class="secondary" id="map-note" style="width:100%;margin-top:20px">＋ Заметка о месте</button>`}
function library(){return SkazCatalog.view()}
function inventoryPage(){return '<section id="inventory-page" aria-label="Инвентарь"><h1>Инвентарь</h1><p role="status">Загружаем предметы…</p></section>';}
function concentrationQuestion(){const check=state.concentrationChecks?.[0];if(!check||!state.concentration||check.spell!==state.concentration)return '';return `<div class="concentration-question" role="status"><strong>Проверка концентрации · СЛ ${check.dc}</strong><span>Урон ${check.damage} · осталось ${state.concentrationChecks.length}</span><div>${[['pass','Прошёл'],['fail','Провалил']].map(([answer,label])=>`<button data-concentration-answer="${answer}" data-check-id="${esc(check.id)}" data-snapshot="${esc(SkazStorage.snapshotKey())}" ${(SkazStorage.canResource?.()??SkazStorage.editable())?'':'disabled'}>${label}</button>`).join('')}</div></div>`;}
function answerConcentration(answer,id,snapshot){if(!['pass','fail'].includes(answer)||snapshot!==SkazStorage.snapshotKey()||state.concentrationChecks?.[0]?.id!==id)return toast('Проверка изменилась. Открой текущую игру');return resourceAction({kind:'health',operation:answer,checkId:id,temporaryBefore:state.tempHp||0,concentrationBefore:state.concentration},1,answer==='pass'?'Концентрация сохранена':'Концентрация провалена');}
function healthVitals(){const d=SkazHealth.deathState(state.hp,state.deathSaves),low=state.hp>0&&state.hp<=state.maxHp/4;const hp=`<strong aria-label="Хиты: ${state.hp} из ${state.maxHp}">${state.hp}/${state.maxHp} <span>ХИТЫ</span><i class="quick-health-meter" aria-hidden="true"><i style="width:${100*state.hp/(state.maxHp+(state.tempHp||0))}%"></i>${state.tempHp?`<i class="hp-temporary" style="width:${100*state.tempHp/(state.maxHp+state.tempHp)}%"></i>`:''}</i>${state.tempHp?`<span class="temp-hp-chip">+${state.tempHp} временных</span>`:''}</strong>`;
 if(state.hp>0)return `<div class="quick-vitals ${low?'wounded':''}">${hp}${low?'<span class="health-state-label">Тяжело ранен</span>':''}<button data-health="damage" class="red">− Урон</button><button data-health="heal" class="green">+ Лечение</button></div>`;
 const label={dying:'Без сознания',stable:'Стабилизирован · без сознания',dead:'Погиб'}[d.status];return `<div class="quick-vitals zero-hp">${hp}<strong class="health-state-label">${label}</strong><button id="death-saves">Успехи ${'●'.repeat(d.successes)+'○'.repeat(3-d.successes)} · Провалы ${'●'.repeat(d.failures)+'○'.repeat(3-d.failures)}</button><button data-health="heal" ${d.status==='dead'?'disabled':''}>+ Лечение — очнуться</button></div>`;}
function deathDialog(){const d=SkazHealth.deathState(state.hp,state.deathSaves),key=SkazStorage.snapshotKey();if(state.hp!==0)return;modal(`<h2>Спасброски от смерти</h2><p>${{dying:'Без сознания',stable:'Стабилизирован · без сознания',dead:'Погиб'}[d.status]}</p><p>Успехи: ${d.successes}/3 · Провалы: ${d.failures}/3</p><div class="death-actions">${[['death-success','Успех (итог ≥10)'],['death-failure','Провал (итог <10)'],['death-1','Натуральная 1 · два провала'],['death-20','Натуральная 20 · 1 хит'],['death-stabilize','Стабилизировать']].map(([op,label])=>`<button data-death-operation="${op}" ${d.status!=='dying'?'disabled':''}>${label}</button>`).join('')}<button id="death-damage" ${d.status==='dead'?'disabled':''}>Урон при 0 хитов</button><button id="death-critical" ${d.status==='dead'?'disabled':''}>Критический урон при 0 хитов</button></div><p>Бросок выполняется вручную. При 0 хитов урон означает провал, критический — два. Натуральная 20 восстанавливает 1 хит. Обычное лечение не воскрешает погибшего.</p>`);
 $$('[data-death-operation]').forEach(b=>b.onclick=()=>{if(key!==SkazStorage.snapshotKey())return toast('Игра изменилась. Открой спасброски заново');const r={kind:'health',operation:b.dataset.deathOperation,temporaryBefore:state.tempHp||0,concentrationBefore:state.concentration,deathBefore:SkazHealth.deathState(state.hp,state.deathSaves)},p=SkazHealth.project(state.hp,state.maxHp,state.tempHp||0,r,1);const apply=()=>{if(resourceAction(r,1,b.textContent)){closeModal();}};if(p.deathSaves.status==='dead')confirmDeath(apply,key);else apply();});$('#death-damage').onclick=()=>hpDialog(false,false);$('#death-critical').onclick=()=>hpDialog(false,true);}
function confirmDeath(apply,key){modal('<h2>Подтвердить гибель?</h2><p>Это действие приведёт к состоянию «Погиб». Можно отменить его после применения.</p><button id="confirm-death" class="primary">Подтвердить гибель</button><button id="cancel-death">Отказаться</button>');let used=false;$('#confirm-death').onclick=()=>{if(used)return;if(key!==SkazStorage.snapshotKey())return toast('Игра изменилась. Проверь действие заново');used=true;apply();};$('#cancel-death').onclick=closeModal;}
function quickPanel(){return `${healthVitals()}<div class="quick-concentration-row ${state.concentrationChecks?.length?'concentration-pending':''}">${state.concentration?`<span class="quick-concentration" title="Концентрация: ${esc(state.concentration)}"><span data-ui-icon="focus"></span> ${esc(state.concentration)}</span><button id="quick-end-concentration" data-concentration="${esc(state.concentration)}" data-snapshot="${esc(SkazStorage.snapshotKey())}" aria-label="Завершить концентрацию: ${esc(state.concentration)}" ${SkazStorage.editable()?'':'disabled'}>Снять</button>`:'<span class="quick-concentration">Без концентрации</span>'}${concentrationQuestion()}</div><div class="quick-resources" tabindex="0" aria-label="Ресурсы: нажми заполненную — потратить, пустую — вернуть">${resourceControls()}</div><div class="quick-extras"><button id="rest" class="secondary"><span data-ui-icon="rest"></span> Отдых</button><button id="quick-note" aria-label="Быстрая личная заметка" ${SkazStorage.editable()?'':'disabled'}><span data-ui-icon="note"></span> Заметка</button><button id="quick-pending" ${SkazStorage.pendingCount?.()?'':'hidden'} aria-label="Не подтверждено сервером: ${SkazStorage.pendingCount?.()||0}. Открыть состояние сохранения">● ${SkazStorage.pendingCount?.()||0}</button></div>`;}
function render(){document.body.dataset.page=page;document.body.dataset.hpState=state.hp===0?'zero':'normal';$$('[data-play-mode]').forEach(b=>b.setAttribute('aria-pressed',String((page==='play'?'play':'prepare')===b.dataset.playMode)));document.body.dataset.examples=SkazStorage.showExamples?.()?'show':'hide';SkazStorage.paint();if(SkazStorage.readyToDisplay?.()===false){document.body.dataset.theme=state.theme;$('#campaign-name').textContent='';$('#session-name-label').textContent='Открываем игру…';$('#quick-state').innerHTML='';$('#main').innerHTML='<div class="panel" role="status"><h1>Открываем твою игру</h1><p>Загружаем сохранённый лист и проверяем доступ.</p></div>';return;}document.getElementById('session-name-label').textContent=[state.profile.name,SkazStorage.sessionTitle(),SkazStorage.sessionDate()].filter(Boolean).join(' · ');$('#campaign-name').textContent=state.profile.campaign;$("#quick-state").innerHTML=quickPanel();document.body.dataset.theme=state.theme;$('#main').innerHTML=({hero,spells:spellsPage,journal,quests,map:mapPage,library,inventory:inventoryPage,play:()=>SkazPlay.view()}[page]||hero)();$$('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.closest('nav')) b.setAttribute('aria-current',b.dataset.page===page?'page':'false')});$$('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===state.theme)));const pendingCount=location.protocol==='file:'?pending().length:SkazEvents.pendingCount();$('#pending-count').textContent=Number.isInteger(pendingCount)&&pendingCount>0?String(pendingCount):'';$('#pending-count').hidden=!(Number.isInteger(pendingCount)&&pendingCount>0);SkazStorage.decorate?.();if(page==='inventory')void SkazStorage.inventory({preserveDialog:true});}
function go(p){if(!['hero','spells','journal','quests','map','library','inventory','play'].includes(p))p='hero';page=p;if(typeof SkazPlay!=='undefined')SkazPlay.remember(p);history.replaceState(null,'','#'+p);render();window.scrollTo({top:0,behavior:'instant'})}
function modal(html){
 const menu=document.getElementById('session-menu');if(menu)menu.open=false;
 const dialog=$('#dialog'),content=$('#dialog-content');
 content.innerHTML=html;SkazStorage.decorate?.(content);
 if(!dialog.open)dialog.showModal();
 content.scrollTop=0;
 content.scrollLeft=0;
 content.focus({preventScroll:true});
}
function closeModal(){$('#dialog').close()}
let toastTimer,toastVersion=0;function toast(text,undo,{error=false,persistent=false}={}){clearTimeout(toastTimer);const version=++toastVersion;let used=false;$('#toast').dataset.kind=error?'error':'success';$('#toast').innerHTML=`<span>${esc(text)}</span>${undo?'<button id="undo">Отменить</button>':''}`;$('#toast').classList.add('show');if(undo)$('#undo').onclick=()=>{if(used||version!==toastVersion)return;used=true;clearTimeout(toastTimer);$('#undo').disabled=true;$('#toast').classList.remove('show');return undo()};if(!persistent)toastTimer=setTimeout(()=>{if(version===toastVersion){toastVersion++;$('#toast').classList.remove('show')}},undo?12000:5000)}
function canChange(){
 if(SkazStorage.editable())return true;
 const message='Сначала обнови игру или заверши сохранение. Введённые данные остаются в форме.';
 if($('#dialog').open){
  let warning=document.getElementById('blocked-form-message');
  if(!warning){warning=document.createElement('p');warning.id='blocked-form-message';warning.className='notice';warning.setAttribute('role','alert');$('#dialog-content').append(warning);}
  warning.textContent=message;warning.scrollIntoView({block:'nearest',behavior:'instant'});
 }else toast(message);
 return false;
}
async function change(label,fn,{undoable=true}={}){
  if(!canChange()){render();return}
  const before=structuredClone(state);
  const contextBefore=SkazStorage.contextKey();
  try{
    fn();
    if(undoable&&before.concentration!==state.concentration&&state.concentrationChecks)state.concentrationChecks=[];
    if(state.deathSaves&&state.hp>0)state.deathSaves={successes:0,failures:0,status:'alive'};
    const next=structuredClone(state);
    state=before;
    const result=await SkazStorage.commit(next,label);
    state={...(result?.state||next),theme:state.theme};
    render();
    const savedKey=SkazStorage.snapshotKey();
    const undo=undoable&&contextBefore===SkazStorage.contextKey()?()=>{if(contextBefore!==SkazStorage.contextKey())return toast('Эта отмена относится к другой игре');if(savedKey!==SkazStorage.snapshotKey())return toast('Игра изменилась. Эта отмена больше недоступна');return change('Отмена: '+label,()=>{state={...structuredClone(before),theme:state.theme}},{undoable:false})}:undefined;
    toast(label,undo);
  }catch(error){state=before;render();toast('Не сохранено: '+error.message)}
}
function log(title,text='',kind='Изменение'){text=state.profile.name+': '+text;((SkazStorage.can?.('shared')??true)?state.journal:state.notes).push({title,text,kind,at:Date.now(),time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})})}
function resourceAction(resource,delta,label,undoable=true,targetMutationId){
 const context=SkazStorage.contextKey();
 try{
  const command=SkazStorage.resourceDelta(resource,delta,SkazStorage.snapshotKey(),targetMutationId),generation=SkazStorage.resourceGeneration();
  const health=resource.kind==='health'?SkazHealth.project(command.before,command.maximum,command.resource.temporaryBefore,command.resource,delta,command.resource.concentrationBefore,command.resource.checksBefore,command.mutationId):null;
  const after=health?health.hp:resource.kind==='hp'?Math.max(0,Math.min(command.maximum,command.before+delta)):command.before+delta,actual=after-command.before;
  const inverse=health?{kind:'health',operation:'restore',temporaryBefore:health.tempHp,hpAfter:command.before,tempAfter:resource.temporaryBefore,concentrationBefore:health.concentration,concentrationAfter:command.resource.concentrationBefore,checksAfter:command.resource.checksBefore||[],deathAfter:command.resource.deathBefore}:resource;
  const undo=undoable&&(actual||health&&(health.tempHp!==resource.temporaryBefore||health.concentration!==resource.concentrationBefore||JSON.stringify(health.concentrationChecks||[])!==JSON.stringify(command.resource.checksBefore||[])||JSON.stringify(health.deathSaves)!==JSON.stringify(command.resource.deathBefore)))?()=>{if(context!==SkazStorage.contextKey()||generation!==SkazStorage.resourceGeneration())return toast('После этого были другие действия. Открой историю для сверки');resourceAction(inverse,health?1:-actual,'Отмена: '+label,false,command.mutationId);}:undefined;
  toast(label+' · записано в очередь',undo);return true;
 }catch(error){toast(error.message,undefined,{error:true,persistent:true});return false;}
}
const healthRecent=new Map();
function hpDialog(heal=false,critical=false){
 if(state.deathSaves?.status==='dead')return toast('Обычное лечение не воскрешает погибшего');
 const openedKey=SkazStorage.snapshotKey(),context=(typeof SkazAccount==='undefined'?'local':SkazAccount.userId||'local')+':'+SkazStorage.contextKey(),old=state.hp;
 let temporary=false,resistance=false,vulnerability=false,submitted=false;const recent=healthRecent.get(context)||[];
 modal('<div class="hp-entry"><div class="overline">ЗДОРОВЬЕ · '+old+'/'+state.maxHp+'</div><h2 id="hp-title">'+ (heal?'Восстановить хиты':'Получить урон')+'</h2><div class="hp-tabs" role="group" aria-label="Операция здоровья"><button id="hp-damage">Урон</button><button id="hp-heal">Лечение</button><button id="hp-temporary">Временные</button></div><label id="hp-label" for="hp-value">'+(heal?'Количество лечения':'Итоговый урон после всех эффектов')+'</label><input id="hp-value" type="number" inputmode="numeric" min="1" max="999" value="" autocomplete="off"><div id="hp-factors" class="hp-factors" role="group" aria-label="Модификатор урона"><button id="hp-half">Сопротивление ÷2</button><button id="hp-double">Уязвимость ×2</button></div><p id="hp-preview" aria-live="polite">Введи количество</p><div id="hp-bar" class="hp-preview-bar" aria-hidden="true"></div><p id="hp-concentration" class="hp-concentration" aria-live="polite"></p><div class="hp-keypad">'+['1','2','3','4','5','6','7','8','9','⌫','0','+5'].map(key=>'<button type="button" data-hp-key="'+key+'" aria-label="'+(key==='⌫'?'Удалить последнюю цифру':key)+'">'+key+'</button>').join('')+'</div><div class="hp-recent" role="group" aria-label="Недавние значения">'+recent.map(n=>'<button type="button" data-hp-recent="'+n+'">'+n+'</button>').join('')+'</div><div class="dialog-actions"><button class="primary" id="apply-hp" disabled>Применить</button></div></div>');
 const field=$('#hp-value'),apply=$('#apply-hp'),preview=$('#hp-preview');
 const value=()=>Number(field.value),valid=()=>Number.isInteger(value())&&value()>=(temporary?0:1)&&value()<=999&&field.value!=='';
 const amount=()=>heal||temporary?value():Math.floor(value()/(resistance?2:1))*(vulnerability?2:1);
 const result=()=>SkazHealth.project(old,state.maxHp,state.tempHp||0,{kind:'health',operation:temporary?'temporary':heal?'heal':critical?'critical-damage':'damage',temporaryBefore:state.tempHp||0,concentrationBefore:state.concentration,deathBefore:SkazHealth.deathState(state.hp,state.deathSaves)},amount());
 const update=()=>{
  const ok=valid(),n=amount(),projection=ok&&(n||temporary)?result():{hp:old,tempHp:state.tempHp||0},next=projection.hp,excess=temporary?0:heal?Math.max(0,old+n-state.maxHp):Math.max(0,n-old-(state.tempHp||0));
  apply.disabled=!ok||(!n&&!temporary)||submitted;
  preview.textContent=ok?(temporary?'Временные: '+(state.tempHp||0)+' → '+projection.tempHp+' · не складываются':old+' → '+next+' хитов'+((state.tempHp||0)?' · временные '+state.tempHp+' → '+projection.tempHp:''))+(projection.deathSaves?.status==='dead'?' · Погиб':next===0?' · Без сознания':'')+(excess?' · '+(heal?'Сверх максимума: ':'Урон сверх оставшихся хитов: ')+excess:''):'Введи целое число от '+(temporary?'0':'1')+' до 999';
  apply.textContent=ok?(temporary?'Заменить временные на '+n:'Применить '+(heal?'+':'−')+n):'Применить';
  field.min=temporary?'0':'1';$('#hp-title').textContent=temporary?'Временные хиты':heal?'Восстановить хиты':critical?'Критический урон':'Получить урон';$('#hp-label').textContent=temporary?'Новый запас (можно оставить прежний, закрыв окно)':heal?'Количество лечения':'Урон одного типа до сопротивления и уязвимости';
  $('#hp-damage').setAttribute('aria-pressed',String(!heal&&!temporary));$('#hp-heal').setAttribute('aria-pressed',String(heal&&!temporary));$('#hp-temporary').setAttribute('aria-pressed',String(temporary));$('#hp-factors').hidden=heal||temporary;
  $('#hp-half').setAttribute('aria-pressed',String(resistance));$('#hp-double').setAttribute('aria-pressed',String(vulnerability));
  const scale=state.maxHp+Math.max(state.tempHp||0,projection.tempHp);
  $('#hp-bar').innerHTML='<i style="width:'+100*Math.min(old,ok?next:old)/scale+'%"></i>'+(ok&&next!==old?'<i class="'+(heal?'hp-gained':'hp-lost')+'" style="width:'+100*Math.abs(next-old)/scale+'%"></i>':'')+(projection.tempHp?'<i class="hp-temporary" style="width:'+100*projection.tempHp/scale+'%"></i>':'');
  const stats=SkazStorage.stats?.(),sheet=SkazStorage.sheet?.(),bonus=stats?Math.floor((stats.abilities.con-10)/2)+((sheet?.saveProficiencies||[]).includes('con')?2+Math.floor((sheet.level-1)/4):0):null;
  $('#hp-concentration').textContent=!heal&&!temporary&&state.concentration&&ok&&n?(next===0?'При 0 хитов концентрация «'+state.concentration+'» завершится.':'Концентрация «'+state.concentration+'»: Телосложение Сл '+Math.max(10,Math.floor(n/2))+(bonus!==null?' · твой бонус '+(bonus>=0?'+':'')+bonus:'')+'. После урона проверь концентрацию.') :'';
 };
 for(const [id,mode] of [['#hp-damage',false],['#hp-heal',true]])$(id).onclick=()=>{heal=mode;temporary=false;resistance=false;vulnerability=false;update();};
 $('#hp-temporary').onclick=()=>{temporary=true;resistance=false;vulnerability=false;update();};
 $('#hp-half').onclick=()=>{resistance=!resistance;update();};$('#hp-double').onclick=()=>{vulnerability=!vulnerability;update();};
 field.oninput=update;
 $$('[data-hp-key]').forEach(button=>button.onclick=()=>{const key=button.dataset.hpKey;field.value=key==='⌫'?field.value.slice(0,-1):key==='+5'?String(Math.min(999,(Number(field.value)||0)+5)):(field.value+key).slice(0,3);update();});
 $$('[data-hp-recent]').forEach(button=>button.onclick=()=>{field.value=button.dataset.hpRecent;update();});
 field.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();return apply.onclick();}};
 apply.onclick=()=>{
  if(submitted)return;
  if(!valid()||(!amount()&&!temporary)){update();return;}
  if(openedKey!==SkazStorage.snapshotKey()){toast('Игра изменилась. Открой ввод здоровья заново');return;}
  if(SkazStorage.resourceDelta&&location.protocol!=='file:'?!SkazStorage.canResource():!canChange())return;
  const n=amount(),projection=result(),next=projection.hp;
  const concentration=!heal&&!temporary&&state.concentration?(next===0?' · Концентрация завершена':' · Проверь концентрацию: Телосложение Сл '+Math.max(10,Math.floor(n/2))):'';
  const remember=()=>{healthRecent.set(context,[value(),...recent.filter(x=>x!==value())].slice(0,3));if(healthRecent.size>50)healthRecent.delete(healthRecent.keys().next().value);submitted=true;apply.disabled=true;};
  if(SkazStorage.resourceDelta&&location.protocol!=='file:'){const applyHealth=()=>{if(resourceAction({kind:'health',operation:temporary?'temporary':heal?'heal':critical?'critical-damage':'damage',temporaryBefore:state.tempHp||0,concentrationBefore:state.concentration},n,(temporary?'Временные '+(state.tempHp||0)+' → '+projection.tempHp:(heal?'+':'−')+n+' хитов · '+old+' → '+next)+concentration)){remember();closeModal();}};if(projection.deathSaves?.status==='dead')confirmDeath(applyHealth,openedKey);else applyHealth();return;}
  const applyDemo=()=>{remember();closeModal();return change((heal?'+':'−')+n+' хитов · '+old+' → '+next+concentration,()=>{Object.assign(state,projection);log(temporary?'Временные хиты':heal?'Лечение':'Получен урон',old+' → '+next+' хитов');});};if(projection.deathSaves?.status==='dead')return confirmDeath(applyDemo,openedKey);return applyDemo();
 };
 update();
}

function openSpell(id){const s=spells.find(s=>s.id===id);if(!s)return;modal(`<div class="overline">${s.level?s.level+' КРУГ':'ЗАГОВОР'} · ${s.school}</div><h2>${s.name}</h2><p>${s.en} · D&D 5e 2014</p><div class="detail-grid"><div><small>ВРЕМЯ</small><strong>${s.time}</strong></div><div><small>ДИСТАНЦИЯ</small><strong>${s.range}</strong></div><div><small>ДЛИТЕЛЬНОСТЬ</small><strong>${s.duration}</strong></div><div><small>КОНЦЕНТРАЦИЯ</small><strong>${s.conc?'Да':'Нет'}</strong></div></div><p>${s.effect}</p>${(SkazStorage.manualStats?.()||SkazStorage.sheet?.())?'<p>Демо-применение отключено для ручного листа. Используй заклинания из каталога и внеси итоговый результат вручную.</p>':''}${s.known?`${s.level?`<label for="cast-level">Использовать ячейку</label><select id="cast-level">${[1,2,3].filter(l=>l>=s.level).map(l=>`<option value="${l}" ${state.slots[l]===0?'disabled':''}>${l} круг · осталось ${state.slots[l]}</option>`).join('')}</select>`:''}${id==='word'?`<label for="heal-target">Цель лечения</label><select id="heal-target"><option value="ally">Союзник — записать применение</option><option value="self">${esc(state.profile.name)} — применить лечение</option></select>`:''}${s.conc&&state.concentration?`<p class="red">Текущая концентрация «${esc(state.concentration)}» завершится при применении.</p>`:''}<div class="dialog-actions"><button class="primary" id="cast-spell" ${(SkazStorage.manualStats?.()||SkazStorage.sheet?.())||s.level&&![1,2,3].some(l=>l>=s.level&&state.slots[l]>0)?'disabled':''}>${s.level?'Применить заклинание':'Применить заговор'}</button></div>`:`<div class="notice">${esc(state.profile.name)} не знает это демонстрационное заклинание. Оно доступно для ознакомления.</div>`}`);if($('#cast-spell'))$('#cast-spell').onclick=()=>{if(SkazStorage.manualStats?.()||SkazStorage.sheet?.())return toast('Для ручного листа используй заклинания из каталога');const level=s.level?Number($('#cast-level').value):0;if(s.level&&(!level||!state.slots[level])){toast('Нет доступной ячейки');return}const self=id==='word'&&$('#heal-target').value==='self';if(!canChange())return;closeModal();let result='';change(s.name+' — применено',()=>{if(level)state.slots[level]--;if(s.conc)state.concentration=s.name;if(self){let total=4;for(let i=0;i<level;i++)total+=1+Math.floor(Math.random()*4);let old=state.hp;state.hp=Math.min(state.maxHp,state.hp+total);result=`Лечение ${total}: ${old} → ${state.hp} хитов. `}log(s.name,result+(level?`Потрачена ячейка ${level} круга.`:'Ячейка не требуется.')+(s.conc?' Концентрация активна.':''),'Магия')})}}
function acceptEvent(id,amount){const e=events.find(e=>e.id===id);if(!e||!pending().some(e=>e.id===id))return;change('Событие добавлено в журнал',()=>{state.accepted.push(id);state.eventEdits[id]=amount;if(id==='gold'){state.gold+=amount??25;log(`Награда: ${amount??25} зм`,e.source,'Из разговора')}else if(id==='damage'){let old=state.hp;Object.assign(state,SkazHealth.project(state.hp,state.maxHp,state.tempHp||0,{operation:'damage',temporaryBefore:state.tempHp||0,concentrationBefore:state.concentration},amount??7));log(`Получен урон: ${amount??7}`,`${old} → ${state.hp} хитов. ${e.source}`,'Из разговора')}else log(e.title,e.source,'Зацепка')})}
function endConcentration(expected,key){
 if(key!==SkazStorage.snapshotKey() || !expected || state.concentration!==expected)return toast('Концентрация или игра изменились. Проверь текущий лист.');
 return change('Концентрация завершена: '+expected,()=>{state.concentration=null;});
}
function quickNote(){
 const key=SkazStorage.snapshotKey();let submitted=false;
 modal('<section class="quick-note-entry"><h2>Личная заметка</h2><label for="quick-note-body">Что запомнить</label><textarea id="quick-note-body" maxlength="2000" placeholder="Enter — сохранить, Shift+Enter — новая строка"></textarea><p class="small">Запись сохранится в личных заметках героя. Общий журнал не меняется.</p><button id="quick-note-save" class="primary">Сохранить заметку</button></section>');
 const submit=()=>{if(submitted)return;if(key!==SkazStorage.snapshotKey())return toast('Игра изменилась. Скопируй текст и открой заметку заново.');const text=$('#quick-note-body').value.trim();if(!text)return toast('Напиши текст заметки');if(text.length>2000)return toast('Не больше 2000 символов');if(!canChange())return;submitted=true;closeModal();return change('Личная заметка сохранена',()=>state.notes.push({title:'Моя заметка',text,at:Date.now(),time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}));};
 $('#quick-note-save').onclick=submit;$('#quick-note-body').onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();return submit();}};$('#quick-note-body').focus();
}
function addNote(map=false){modal(`<div class="overline">${map?esc(places[place].title):'ЛИЧНЫЙ ЖУРНАЛ'}</div><h2>${map?'Заметка о месте':'Запомнить важное'}</h2><label for="note-body">Текст заметки</label><textarea id="note-body" maxlength="2000" placeholder="Что важно не забыть…"></textarea><div class="dialog-actions"><button class="primary" id="save-note">Сохранить</button></div>`);$('#save-note').onclick=()=>{let text=$('#note-body').value.trim();if(!text){toast('Напиши текст заметки');return}if(!canChange())return;closeModal();change('Заметка сохранена',()=>{if(map)state.mapNotes.push({place,text});else state.notes.push({title:'Моя заметка',text,at:Date.now(),time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})})})}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b||b.disabled||SkazCharacterSheet.suppressTrackerClick(e))return;if(b.dataset.concentrationAnswer){answerConcentration(b.dataset.concentrationAnswer,b.dataset.checkId,b.dataset.snapshot);return}if(b.dataset.health){hpDialog(b.dataset.health==='heal');return}if(b.dataset.resource){
 if(SkazStorage.sheet?.()||(SkazStorage.resourceDelta&&location.protocol!=='file:'?!SkazStorage.canResource():!canChange()))return;
 const key=b.dataset.resource,delta=Number(b.dataset.delta),level=Number(key.slice(4));
 if(![-1,1].includes(delta)||!(key==='inspiration'||[1,2,3].includes(level)&&key==='slot'+level))return;
 const before=key==='inspiration'?state.inspiration:state.slots[level],max=key==='inspiration'?4:[4,3,2][level-1],next=before+delta;
 if(next<0||next>max)return;
 const title=key==='inspiration'?'Вдохновение барда · к8':level+' круг';
 if(SkazStorage.resourceDelta&&location.protocol!=='file:'){resourceAction(key==='inspiration'?{kind:'inspiration'}:{kind:'slot',level},delta,title+': '+before+' → '+next);return;}
 change(title+': '+before+' → '+next,()=>{if(key==='inspiration')state.inspiration=next;else state.slots[level]=next;log(title,before+' → '+next,'Ресурс')});return;
 }if(b.dataset.page){go(b.dataset.page);return}if(b.dataset.themeChoice){state.theme=b.dataset.themeChoice;save();render();return}if(b.dataset.spell){openSpell(b.dataset.spell);return}if(b.dataset.accept){acceptEvent(b.dataset.accept);return}if(b.dataset.dismiss){change('Событие пропущено',()=>state.dismissed.push(b.dataset.dismiss));return}if(b.dataset.editEvent){const id=b.dataset.editEvent;if(id==='quest'){modal('<div class="overline">РЕДАКТИРОВАНИЕ ЗАЦЕПКИ</div><h2>Уточнить услышанное</h2><label for="event-text">Текст зацепки</label><textarea id="event-text">Картограф не вернулся с маяка</textarea><div class="dialog-actions"><button class="primary" id="save-event">Сохранить в журнал</button></div>');$('#save-event').onclick=()=>{const text=$('#event-text').value.trim();if(!text)return;if(!canChange())return;closeModal();change('Уточнённая зацепка сохранена',()=>{state.accepted.push(id);state.eventEdits.quest=text;log(text,events.find(e=>e.id==='quest').source,'Зацепка')})}}else{modal(`<h2>Уточнить ${id==='gold'?'награду':'урон'}</h2><label for="event-value">Количество</label><input id="event-value" type="number" min="0" max="9999" value="${id==='gold'?25:7}"><div class="dialog-actions"><button class="primary" id="save-event">Подтвердить</button></div>`);$('#save-event').onclick=()=>{let n=Number($('#event-value').value);if(!Number.isInteger(n)||n<0||n>9999){toast('Укажи целое число от 0 до 9999');return}if(!canChange())return;closeModal();acceptEvent(id,n)}}return}if(b.dataset.place){place=b.dataset.place;go('map');return}if(b.dataset.mapPlace){place=b.dataset.mapPlace;render();return}if(b.classList.contains('dialog-close')){closeModal();return}if(b.dataset.roll){const r=1+Math.floor(Math.random()*20);modal(`<div class="overline">БРОСОК АТАКИ · РАПИРА</div><h2>${r+5} <span style="font-size:16px;color:var(--muted)">= ${r} + 5</span></h2><p>Демо-бросок к20. ${r===20?'Натуральная 20!':r===1?'Натуральная 1.':'Сравни результат с КД цели.'} Урон и попадание подтверждает мастер.</p>`);return}
switch(b.id){case'death-saves':deathDialog();break;case'play-note':case'quick-note':quickNote();break;case'quick-end-concentration':endConcentration(b.dataset.concentration,b.dataset.snapshot);break;case'quick-pending':{const menu=document.getElementById('session-menu');if(menu){menu.open=true;menu.querySelector?.('summary')?.focus();}break;}case'edit-profile':editProfile();break;case'damage':hpDialog();break;case'heal':hpDialog(true);break;case'add-note':addNote();break;case'map-note':addNote(true);break;case'pause':paused=!paused;render();break;case'restore-events':change('Пропущенные события возвращены',()=>{state.dismissed=[]});break;case'inspire':if(SkazStorage.sheet?.()){toast('Счётчики своего класса изменяются вручную');break;}if(state.inspiration>0)change('Вдохновение передано союзнику',()=>{state.inspiration--;log('Бардовское вдохновение','Союзник получает к8; осталось '+state.inspiration+'/4','Способность')});break;case'rest':if(state.hp===0){toast('При 0 хитах сначала нужна помощь или стабилизация');break;}if(SkazStorage.sheet?.()){const restKey=SkazStorage.snapshotKey();modal('<h2>Длительный отдых</h2><p>Если по правилам отдыха можно восстановить хиты, восстанови их до максимума и сними временные. Счётчики класса и кости хитов проверь вручную. Концентрация будет завершена.</p><button id="long-rest" class="primary">Восстановить хиты после отдыха</button>');$('#long-rest').onclick=()=>{if(restKey!==SkazStorage.snapshotKey())return toast('Игра изменилась. Открой отдых заново');if(!canChange())return;closeModal();change('Хиты после длительного отдыха',()=>{state.hp=state.maxHp;state.tempHp=0;state.concentration=null;log('Длительный отдых','Хиты восстановлены, временные сняты. Счётчики класса проверяются вручную.');});};break;}modal(`<div class="overline">ПЕРЕДЫШКА</div><h2>Время перевести дух</h2><p>В демо долгий отдых восстанавливает хиты, ячейки и вдохновение. Короткий отдых на 5 уровне восстанавливает вдохновение барда; кости хитов здесь ещё не реализованы.</p><div class="dialog-actions"><button id="short-rest">Короткий</button><button class="primary" id="long-rest">Долгий</button></div>`);$('#short-rest').onclick=()=>{if(!canChange())return;closeModal();change('Короткий отдых завершён',()=>{state.inspiration=4;log('Короткий отдых','Вдохновение восстановлено. Кости хитов не потрачены.')})};$('#long-rest').onclick=()=>{if(!canChange())return;closeModal();change('Долгий отдых завершён',()=>{state.hp=state.maxHp;state.tempHp=0;state.slots={1:4,2:3,3:2};state.inspiration=4;state.concentration=null;log('Долгий отдых','Хиты, ячейки и вдохновение восстановлены.')})};break;case'export-journal':{const text=['СКАЗ · '+SkazStorage.sessionTitle(),SkazStorage.sessionDate(),state.profile.campaign,'',...state.journal.map(e=>`${e.time} · ${e.title}\n${e.text}`),'Личные заметки персонажа (между сессиями)',...state.notes.map(e=>`${e.time} · ${e.title}\n${e.text}`)].join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='skaz-journal.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Журнал подготовлен для скачивания');break}case'about-library':case'about':SkazStorage.settings();break;}});
document.addEventListener('input',e=>{if(e.target.id==='spell-search'){spellQuery=e.target.value;$('#spell-results').innerHTML=spellCards()}});
